"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  INTERACTION_PRESS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * EXPANDING BUTTON GROUP: an icon toolbar that names what you point at
 *
 *   point    the action under the mouse (or keyboard focus) opens
 *            its label; the column eases from 0fr to 1fr while the
 *            text lifts out of a blur, so neighbours slide aside
 *            instead of jumping. Each change retargets mid-way.
 *   tap      on touch nothing hovers: a tap acts and opens the
 *            label for a moment, so you see what you pressed
 *   ask      items with `confirm` ask first: the label morphs to
 *            "Delete?" and the next press acts (3s, Esc or moving
 *            away cancels)
 *   done     items with `confirmLabel` answer in place: the icon
 *            gives way to a drawn check, the label morphs
 *
 * Hover follows real pointer movement only, so a label opening
 * under a still cursor never hands the hover to a neighbour.
 * ───────────────────────────────────────────────────────── */

export type ExpandingItemTone = "default" | "primary" | "danger";

export interface ExpandingButtonItem {
  id: string;
  label: string;
  icon: React.ReactNode;
  tone?: ExpandingItemTone;
  /** Ask before acting: the label morphs to this ("Delete?") and the next press runs onClick. */
  confirm?: string;
  /** Shown with a drawn check after the action runs ("Archived"). */
  confirmLabel?: string;
  onClick?: () => void;
  disabled?: boolean;
}

export interface ExpandingButtonGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  items: ExpandingButtonItem[];
  /** The item that stays open while nothing is pointed at (controlled). */
  expandedId?: string | null;
  /** The item that stays open while nothing is pointed at. */
  defaultExpandedId?: string | null;
  /** sm: 24px buttons in a 32px bar. md: 28px buttons in a 36px bar. */
  size?: "sm" | "md";
  /** Accessible name of the toolbar. */
  label?: string;
}

const TONES: Record<ExpandingItemTone, { idle: string; open: string }> = {
  default: {
    idle: "text-muted-foreground hover:text-foreground",
    open: "bg-accent text-foreground",
  },
  primary: {
    idle: "text-muted-foreground hover:text-foreground",
    open: "bg-primary text-primary-foreground",
  },
  danger: {
    idle: "text-muted-foreground hover:text-red-600 dark:hover:text-red-400",
    open: "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_25%,transparent)] dark:text-red-400",
  },
};

const ASK_MS = 3000;
const DONE_MS = 1600;
const TAP_MS = 2400;

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-full">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition: reduced
            ? "none"
            : drawn
              ? `stroke-dashoffset 360ms ${EASE_OUT} 80ms`
              : "stroke-dashoffset 0ms linear 300ms",
        }}
      />
    </svg>
  );
}

export function ExpandingButtonGroup({
  items,
  expandedId,
  defaultExpandedId = null,
  size = "md",
  label = "Actions",
  className = "",
  onKeyDown,
  ...props
}: ExpandingButtonGroupProps) {
  const reduced = useInteractionReducedMotion();
  const groupRef = React.useRef<HTMLDivElement>(null);
  const [hoverId, setHoverId] = React.useState<string | null>(null);
  const [focusId, setFocusId] = React.useState<string | null>(null);
  const [tapId, setTapId] = React.useState<string | null>(null);
  const [askId, setAskId] = React.useState<string | null>(null);
  const [doneId, setDoneId] = React.useState<string | null>(null);
  const [tabStop, setTabStop] = React.useState<string | null>(null);
  const lastPoint = React.useRef({ x: NaN, y: NaN });
  const pointerType = React.useRef("mouse");

  const restId = expandedId !== undefined ? expandedId : defaultExpandedId;
  const openId = hoverId ?? focusId ?? askId ?? doneId ?? tapId ?? restId;
  const firstEnabled = items.find((item) => !item.disabled)?.id ?? null;
  const stop = items.some((item) => item.id === tabStop && !item.disabled)
    ? tabStop
    : firstEnabled;

  // Each transient state lets go on its own.
  React.useEffect(() => {
    if (!askId) return;
    const timer = window.setTimeout(() => setAskId(null), ASK_MS);
    return () => window.clearTimeout(timer);
  }, [askId]);
  React.useEffect(() => {
    if (!doneId) return;
    const timer = window.setTimeout(() => setDoneId(null), DONE_MS);
    return () => window.clearTimeout(timer);
  }, [doneId]);
  React.useEffect(() => {
    if (!tapId) return;
    const timer = window.setTimeout(() => setTapId(null), TAP_MS);
    return () => window.clearTimeout(timer);
  }, [tapId]);

  const point = (id: string | null) => {
    setHoverId(id);
    if (askId && id !== askId) setAskId(null);
  };

  // Hover follows movement, not boundary events: when a label opens under a still cursor,
  // the neighbour that slides beneath it doesn't steal the hover.
  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    pointerType.current = e.pointerType;
    if (e.pointerType !== "mouse") return;
    if (e.clientX === lastPoint.current.x && e.clientY === lastPoint.current.y)
      return;
    lastPoint.current = { x: e.clientX, y: e.clientY };
    const el = (e.target as HTMLElement).closest<HTMLElement>(
      "[data-expanding-item]",
    );
    const item = el
      ? items.find((i) => i.id === el.dataset.expandingItem)
      : undefined;
    if (item && !item.disabled && item.id !== hoverId) point(item.id);
  };

  const handleClick = (item: ExpandingButtonItem) => {
    if (item.disabled) return;
    setTabStop(item.id);
    if (pointerType.current !== "mouse") setTapId(item.id);
    if (item.confirm && askId !== item.id) {
      setDoneId(null);
      setAskId(item.id);
      return;
    }
    setAskId(null);
    item.onClick?.();
    if (item.confirmLabel) setDoneId(item.id);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(e);
    if (e.key === "Escape" && askId) {
      e.preventDefault();
      setAskId(null);
      return;
    }
    const enabled = items.filter((item) => !item.disabled);
    const index = enabled.findIndex((item) => item.id === stop);
    let next = -1;
    if (e.key === "ArrowRight") next = (index + 1) % enabled.length;
    else if (e.key === "ArrowLeft")
      next = (index - 1 + enabled.length) % enabled.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = enabled.length - 1;
    if (next < 0 || !enabled[next]) return;
    e.preventDefault();
    const id = enabled[next].id;
    setTabStop(id);
    groupRef.current
      ?.querySelector<HTMLElement>(`[data-expanding-item="${CSS.escape(id)}"]`)
      ?.focus();
  };

  const sm = size === "sm";
  const iconSize = sm ? 12 : 14;
  const announce = askId
    ? items.find((i) => i.id === askId)?.confirm
    : doneId
      ? items.find((i) => i.id === doneId)?.confirmLabel
      : undefined;

  return (
    <>
      <div
        ref={groupRef}
        role="toolbar"
        aria-label={label}
        onKeyDown={handleKeyDown}
        onPointerDown={(e) => (pointerType.current = e.pointerType)}
        onPointerMove={handlePointerMove}
        onPointerLeave={(e) => {
          // A lifted finger "leaves" too; only a mouse leaving ends the hover (and an open ask).
          if (e.pointerType !== "mouse") return;
          lastPoint.current = { x: NaN, y: NaN };
          point(null);
        }}
        onBlur={(e) => {
          if (groupRef.current?.contains(e.relatedTarget as Node)) return;
          setFocusId(null);
          setAskId(null);
        }}
        className={`relative inline-flex max-w-full select-none items-center gap-0.5 rounded-full bg-card p-1 text-foreground shadow-[inset_0_0_0_1px_var(--border)] ${className}`}
        {...props}
      >
        {items.map((item) => {
          const open = openId === item.id;
          const done = doneId === item.id;
          const tone = TONES[item.tone ?? "default"];
          const text = done
            ? (item.confirmLabel ?? item.label)
            : askId === item.id
              ? (item.confirm ?? item.label)
              : item.label;
          return (
            <button
              key={item.id}
              type="button"
              data-expanding-item={item.id}
              data-state={open ? "open" : "closed"}
              disabled={item.disabled}
              tabIndex={stop === item.id ? 0 : -1}
              onClick={() => handleClick(item)}
              onFocus={(e) => {
                setTabStop(item.id);
                // Keyboard focus opens the label; a tap's focus doesn't (the tap does).
                setFocusId(
                  e.currentTarget.matches(":focus-visible") ? item.id : null,
                );
              }}
              className={`relative inline-flex shrink-0 items-center rounded-full font-medium cursor-pointer disabled:cursor-default disabled:opacity-40 ${INTERACTION_PRESS} ${INTERACTION_FOCUS} ${
                sm ? "h-6 px-1.5 text-[12px]" : "h-7 px-[7px] text-[12.5px]"
              } ${open ? tone.open : tone.idle}`}
            >
              <span
                aria-hidden="true"
                className="relative shrink-0"
                style={{ width: iconSize, height: iconSize }}
              >
                <span
                  className="absolute inset-0 flex items-center justify-center [&_svg]:size-full"
                  style={interactionIcon(!done, reduced)}
                >
                  {item.icon}
                </span>
                <span
                  className={`absolute inset-0 ${item.tone === "primary" && open ? "" : "text-emerald-600 dark:text-emerald-400"}`}
                  style={interactionIcon(done, reduced)}
                >
                  <Check drawn={done} reduced={reduced} />
                </span>
              </span>
              {/* The label's column eases 0fr ↔ 1fr, so the button and its neighbours move as one. */}
              <span
                className="grid"
                style={{
                  gridTemplateColumns: open ? "1fr" : "0fr",
                  transition: reduced
                    ? "none"
                    : `grid-template-columns 400ms ${EASE_OUT}`,
                }}
              >
                <span className="min-w-0 overflow-hidden [clip-path:inset(-4px_0)]">
                  <span
                    className="block w-max whitespace-nowrap pl-1.5 pr-1"
                    style={{
                      opacity: open ? 1 : 0,
                      filter: open ? "blur(0px)" : "blur(4px)",
                      transform: open ? "none" : "translateX(-4px)",
                      transition: reduced
                        ? "none"
                        : open
                          ? `opacity 260ms ${EASE_OUT} 80ms, filter 260ms ${EASE_OUT} 80ms, transform 400ms ${EASE_OUT}`
                          : `opacity 140ms ${EASE_OUT}, filter 140ms ${EASE_OUT}, transform 300ms ${EASE_OUT}`,
                    }}
                  >
                    <TextMorph>{text}</TextMorph>
                  </span>
                </span>
              </span>
            </button>
          );
        })}
      </div>
      <span role="status" className="sr-only">
        {announce ?? ""}
      </span>
    </>
  );
}

export default ExpandingButtonGroup;

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

